static PyObject *mv_into(PyObject *self, PyObject *args) {
    PyObject *indptr_o, *indices_o, *data_o, *workd_o;
    Py_ssize_t xs, ys, n;
    if (!PyArg_ParseTuple(args, "OOOOnn", &indptr_o, &indices_o, &data_o, &workd_o, &xs, &ys))
        return NULL;
    PyArrayObject *indptr = (PyArrayObject *)PyArray_FROM_OTF(indptr_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *indices = (PyArrayObject *)PyArray_FROM_OTF(indices_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *data = (PyArrayObject *)PyArray_FROM_OTF(data_o, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *workd = (PyArrayObject *)PyArray_FROM_OTF(workd_o, NPY_FLOAT64, NPY_ARRAY_INOUT_ARRAY);
    if (!indptr || !indices || !data || !workd) {
        Py_XDECREF(indptr); Py_XDECREF(indices); Py_XDECREF(data); Py_XDECREF(workd);
        return NULL;
    }
    n = PyArray_DIM(indptr, 0) - 1;
    int *ip = (int *)PyArray_DATA(indptr);
    int *idx = (int *)PyArray_DATA(indices);
    double *a = (double *)PyArray_DATA(data);
    double *w = (double *)PyArray_DATA(workd);
    double *x = w + xs;
    double *y = w + ys;
    for (Py_ssize_t i = 0; i < n; i++) {
        double s = 0.0;
        int end = ip[i + 1];
        for (int j = ip[i]; j < end; j++)
            s += a[j] * x[idx[j]];
        y[i] = s;
    }
    Py_DECREF(indptr); Py_DECREF(indices); Py_DECREF(data); Py_DECREF(workd);
    Py_RETURN_NONE;
}

static PyMethodDef methods[] = {
    {"mv_into", mv_into, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "fastmv", NULL, -1, methods};
